assertion_evidence.exact_source:
publish(scope, now.Add(time.Hour), true)
resolver := FoundationResolver{Footprint: reader, Store: store}
if _, err := resolver.ReadAccess(t.Context(), ""); !errors.Is(err, ErrReadAccessPending) {
	t.Fatalf("missing durable record must stay pending: %v", err)
}
records, etags := map[string]FoundationRecord{}, map[string]string{}
for _, intent := range grant.Regions {
	digest, err := FoundationIntentDigest(intent)
	if err != nil {
		t.Fatal(err)
	}
	cell := intent.Plan["cell"].(string)
	ids := map[string]string{}
	for key, id := range intent.Plan["resource_ids"].(map[string]any) {
		ids[key] = id.(string)
	}
	record := FoundationRecord{SchemaVersion: 1, Cell: cell, OCIRegion: intent.Plan["region"].(string), TenancyID: reader.tenancy,
		ParentCompartmentID: grant.ParentCompartmentID, SharedCompartmentID: grant.SharedCompartmentID,
		Generation: 1, IntentDigest: digest, OperationID: entityid.New(), Epoch: 1, Stage: "reconciled",
		StartedAt: now, UpdatedAt: now, CompletedAt: now, ResourceIDs: ids,
		AuxiliaryIDs: map[string]string{"backup_bucket": "ocid1.bucket.oc1." + intent.Plan["region"].(string) + ".owned"}}
	etag, err := store.CompareAndSwap(t.Context(), record, "")
	if err != nil {
		t.Fatal(err)
	}
	records[cell], etags[cell] = record, etag
}
access, err := resolver.ReadAccess(t.Context(), "")
if err != nil || !access.IsVerified() || access.Cell() != "FRA" || access.OCIRegion() != "eu-frankfurt-1" || access.UsageToken() != grant.Regions[1].ReadAccess.UsageToken || !access.ExpiresAt().Equal(now.Add(time.Hour)) {
	t.Fatalf("signed home selection failed: access=%+v err=%v", access, err)
}

urls := access.URLs()
urls[0] = "https://changed.example.test"
if access.URLs()[0] != grant.Regions[1].ReadAccess.URLs[0] {
	t.Fatal("read access exposed mutable signed destinations")
}

if selected, err := resolver.ReadAccess(t.Context(), "GRU"); err != nil || selected.Cell() != "GRU" {
	t.Fatalf("explicit signed region failed: %v", err)
}
if _, err := resolver.ReadAccess(t.Context(), "SFO"); !errors.Is(err, ErrReadAccessPending) {
	t.Fatalf("unsigned region must stay pending: %v", err)
}
backup, err := resolver.BackupDestination(t.Context(), "FRA")
if err != nil || backup.OCIRegion() != "eu-frankfurt-1" || backup.BucketName() != "owned-backups" ||
	backup.BucketID() != records["FRA"].AuxiliaryIDs["backup_bucket"] || backup.VaultTarget().VaultID != grant.Regions[1].ReadAccess.UsageToken.Vault || backup.Check(t.Context()) != nil {
	t.Fatalf("signed current backup destination failed: destination=%+v err=%v", backup, err)
}
for _, id := range []string{"", "ocid1.bucket.oc1.eu-frankfurt-1.replacement"} {
	changed := records["FRA"]
	changed.AuxiliaryIDs = maps.Clone(changed.AuxiliaryIDs)
	if id == "" {
		delete(changed.AuxiliaryIDs, "backup_bucket")
	} else {
		changed.AuxiliaryIDs["backup_bucket"] = id
	}
	etag, err := store.CompareAndSwap(t.Context(), changed, etags["FRA"])
	if err != nil {
		t.Fatal(err)
	}
	if err := backup.Check(t.Context()); err == nil {
		t.Fatal("backup destination outlived its exact durable bucket identity")
	}
	etags["FRA"], err = store.CompareAndSwap(t.Context(), records["FRA"], etag)
	if err != nil {
		t.Fatal(err)
	}
}

original := grant.Regions[1].ReadAccess
for _, scenario := range []string{"no access", "foreign Vault", "plaintext", "credential URL", "path URL", "query URL", "bad port", "wrong signature scope", "expired", "changed pinned wire"} {
	t.Run(scenario, func(t *testing.T) {
		changed := *original
		changed.URLs = append([]string(nil), original.URLs...)
		grant.Regions[1].ReadAccess = &changed
		signedScope, expiry, pin := scope, now.Add(time.Hour), true
		switch scenario {
		case "no access":
			grant.Regions[1].ReadAccess = nil
		case "foreign Vault":
			changed.UsageToken.Vault = "ocid1.vault.oc1.eu-frankfurt-1.foreign"
		case "plaintext":
			changed.URLs[0] = "http://FRA.example.test"
		case "credential URL":
			changed.URLs[0] = "https://user:password@FRA.example.test"
		case "path URL":
			changed.URLs[0] += "/other"
		case "query URL":
			changed.URLs[0] += "?token=value"
		case "bad port":
			changed.URLs[0] += ":65536"
		case "wrong signature scope":
			signedScope.Cell = "FRA"
		case "expired":
			expiry = now.Add(-time.Second)
		case "changed pinned wire":
			changed.URLs[0] = "https://changed.example.test"
			pin = false
		}
		publish(signedScope, expiry, pin)
		if _, err := resolver.ReadAccess(t.Context(), "FRA"); err == nil {
			t.Fatal("unverified regional read access was returned")
		} else if scenario == "no access" && !errors.Is(err, ErrReadAccessPending) {
			t.Fatalf("absent signed access must stay pending: %v", err)
		}
		grant.Regions[1].ReadAccess = original
		publish(scope, now.Add(time.Hour), true)
	})
}
for _, scenario := range []string{"foreign current Vault", "stale generation", "unreconciled"} {
	t.Run(scenario, func(t *testing.T) {
		changed := records["FRA"]
		changed.ResourceIDs = maps.Clone(changed.ResourceIDs)
		switch scenario {
		case "foreign current Vault":
			changed.ResourceIDs["vault"] = "ocid1.vault.oc1.eu-frankfurt-1.foreign"
		case "stale generation":
			changed.Generation++
		case "unreconciled":
			changed.Stage, changed.BlockedReason, changed.CompletedAt = "blocked", "foundation-unavailable", time.Time{}
		}
		etag, err := store.CompareAndSwap(t.Context(), changed, etags["FRA"])
		if err != nil {
			t.Fatal(err)
		}
		if _, err := resolver.ReadAccess(t.Context(), "FRA"); err == nil {
			t.Fatal("read access outlived its current owned reconciled record")
		}
		if err := backup.Check(t.Context()); err == nil {
			t.Fatal("backup destination outlived its current owned reconciled record")
		}
		etags["FRA"], err = store.CompareAndSwap(t.Context(), records["FRA"], etag)
		if err != nil {
			t.Fatal(err)
		}
	})
}

t.Run("mandatory chain even on fresh installation", func(t *testing.T) {
	f := newCurrentDiscoveryScenario(t)
	delete(f.objects, foundationRootChainObject)
	if _, err := f.discover(t.Context()); !errors.Is(err, ErrFoundationDiscoveryPending) {
		t.Fatalf("absent explicit chain: %v", err)
	}
	if _, err := os.Stat(f.floorPath()); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("failed discovery created floor: %v", err)
	}
})

t.Run("rotation persisted before resolver and survives restart", func(t *testing.T) {
	f := newCurrentDiscoveryScenario(t)
	initialRoot := f.root
	f.now = f.now.Add(-48 * time.Hour)
	f.rotate()
	if err := trust.RotationCurrent(f.chain.Rotations[0], time.Now()); !errors.Is(err, trust.ErrExpired) {
		t.Fatalf("fixture rotation must be historical: %v", err)
	}
	f.now = f.now.Add(48 * time.Hour)
	f.publish()
	resolver, err := f.discover(t.Context())
	if err != nil {
		t.Fatal(err)
	}
	wire, err := os.ReadFile(f.floorPath())
	if err != nil {
		t.Fatal(err)
	}
	var floor foundationFloor
	if err := json.Unmarshal(wire, &floor); err != nil {
		t.Fatal(err)
	}
	exactChain, err := trust.EncodeRootChain(f.chain)
	if err != nil || !bytes.Equal(floor.ChainWire, exactChain) || floor.InstallationID != f.grant.InstallationID || floor.Generation != f.grant.Generation {
		t.Fatalf("floor differs from adopted authority: %+v %v", floor, err)
	}
	for path, mode := range map[string]os.FileMode{f.floorPath(): 0600, filepath.Dir(f.floorPath()): 0700} {
		info, err := os.Stat(path)
		if err != nil || info.Mode().Perm() != mode {
			t.Fatalf("unsafe floor permission: %s %v", path, err)
		}
	}
	if _, err := resolver.Footprint.AuthorizedRegions(t.Context()); err != nil {
		t.Fatal(err)
	}
	if _, err := f.discover(t.Context()); err != nil {
		t.Fatalf("restart: %v", err)
	}
	delete(f.objects, foundationRootChainObject)
	if _, err := f.discover(t.Context()); !errors.Is(err, ErrFoundationDiscoveryPending) {
		t.Fatalf("adopted chain omission: %v", err)
	}
	f.chain = trust.RootChain{Version: 1}
	f.root = initialRoot
	f.publish()
	if _, err := f.discover(t.Context()); err == nil {
		t.Fatal("restarted client accepted retired genesis")
	}
	f.rotate()
	f.publish()
	if _, err := f.discover(t.Context()); err == nil {
		t.Fatal("restarted client accepted rival rotation")
	}
})
t.Run("generation and exact grant wire remain monotonic", func(t *testing.T) {
	f := newCurrentDiscoveryScenario(t)
	if _, err := f.discover(t.Context()); err != nil {
		t.Fatal(err)
	}
	f.grant.MonthlyLimitMinor++
	f.publish()
	if _, err := f.discover(t.Context()); err == nil {
		t.Fatal("adopted generation accepted altered grant")
	}
	f.grant.Generation = 2
	f.grant.Regions[0].Generation = 2
	f.publish()
	if _, err := f.discover(t.Context()); err != nil {
		t.Fatalf("new generation: %v", err)
	}
	f.grant.Generation = 1
	f.grant.Regions[0].Generation = 1
	f.publish()
	if _, err := f.discover(t.Context()); err == nil {
		t.Fatal("restarted client accepted lower grant generation")
	}
})
t.Run("identity and anchor authority cannot switch", func(t *testing.T) {
	f := newCurrentDiscoveryScenario(t)
	if _, err := f.discover(t.Context()); err != nil {
		t.Fatal(err)
	}
	f.anchor.InitialSourceRegistration.PlanSHA256 = strings.Repeat("b", 64)
	f.publish()
	if _, err := f.discover(t.Context()); err == nil {
		t.Fatal("same chain and grant accepted changed anchor authority")
	}
	f.grant.Generation = 2
	f.grant.Regions[0].Generation = 2
	f.grant.InstallationID = entityid.New()
	f.anchor.FoundationScope.InstallationID = f.grant.InstallationID
	f.anchor.InitialSourceRegistration.InstallationID = f.grant.InstallationID
	f.publish()
	if _, err := f.discover(t.Context()); err == nil {
		t.Fatal("new generation switched installed identity")
	}
})

t.Run("untrusted roots and foreign location remain rejected", func(t *testing.T) {
	f := newCurrentDiscoveryScenario(t)
	original := f.root
	_, attacker, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	f.root = attacker
	f.publish()
	if _, err := f.discover(t.Context()); err == nil {
		t.Fatal("self-declared locator signer became trusted")
	}
	f.root = original
	f.anchor.StorageDomain.Namespace = "foreign"
	f.anchor.FoundationScope.StorageDomain.Namespace = "foreign"
	f.anchor.InitialSourceRegistration.StorageDomain.Namespace = "foreign"
	f.publish()
	if _, err := f.discover(t.Context()); err == nil {
		t.Fatal("signed locator redirected authenticated storage namespace")
	}

if _, err := DiscoverCurrentFoundation(t.Context(), nil); !errors.Is(err, ErrFoundationDiscoveryPending) {
	t.Fatalf("missing authenticated factory: %v", err)
}

t.Run("absent grant never adopts incomplete authority", func(t *testing.T) {
	f := newCurrentDiscoveryScenario(t)
	delete(f.objects, "bootstrap/"+foundationGrantObject)
	if _, err := f.discover(t.Context()); !errors.Is(err, ErrFoundationGrantPending) {
		t.Fatalf("missing grant: %v", err)
	}
	if _, err := os.Stat(f.floorPath()); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("incomplete authority persisted: %v", err)
	}
})

t.Run("another process fences adoption and cancellation", func(t *testing.T) {
	f := newCurrentDiscoveryScenario(t)
	if _, err := f.discover(t.Context()); err != nil {
		t.Fatal(err)
	}
	command := exec.Command(os.Args[0], "-test.run=^TestCurrentFoundationDiscoveryLockProcess$")
	command.Env = append(os.Environ(), "TS_TEST_FOUNDATION_LOCK="+f.floorPath()+".lock")
	output, err := command.StdoutPipe()
	if err != nil {
		t.Fatal(err)
	}
	input, err := command.StdinPipe()
	if err != nil {
		t.Fatal(err)
	}
	if err := command.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		input.Close()
		if err := command.Wait(); err != nil {
			t.Error(err)
		}
	})
	var marker [1]byte
	if _, err := io.ReadFull(output, marker[:]); err != nil || marker[0] != 'L' {
		t.Fatalf("child did not acquire floor lock: %q %v", marker, err)
	}
	ctx, cancel := context.WithTimeout(t.Context(), 80*time.Millisecond)
	defer cancel()
	if _, err := f.discover(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("waiting discovery ignored lock/cancellation: %v", err)
	}
})

t.Run("unsafe or damaged durable state never resets trust", func(t *testing.T) {
	f := newCurrentDiscoveryScenario(t)
	if _, err := f.discover(t.Context()); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(f.floorPath(), []byte(`{`), 0600); err != nil {
		t.Fatal(err)
	}
	if _, err := f.discover(t.Context()); err == nil {
		t.Fatal("corrupt floor became first-install fallback")
	}
	outside := filepath.Join(t.TempDir(), "outside")
	if err := os.WriteFile(outside, []byte("unchanged"), 0600); err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(f.floorPath()); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(outside, f.floorPath()); err != nil {
		t.Fatal(err)
	}
	if _, err := f.discover(t.Context()); err == nil {
		t.Fatal("symlink floor accepted")
	}
	if wire, err := os.ReadFile(outside); err != nil || string(wire) != "unchanged" {
		t.Fatalf("symlink target changed: %q %v", wire, err)
	}
})

path := os.Getenv("TS_TEST_FOUNDATION_LOCK")
if path == "" {
	return
}
lock, err := os.OpenFile(path, os.O_RDWR, 0600)
if err != nil {
	t.Fatal(err)
}
defer lock.Close()
if err := unix.Flock(int(lock.Fd()), unix.LOCK_EX); err != nil {
	t.Fatal(err)
}
if _, err := os.Stdout.Write([]byte("L")); err != nil {
	t.Fatal(err)
}
var done [1]byte
_, _ = os.Stdin.Read(done[:])

etag, err := store.CompareAndSwap(t.Context(), record, "")
if err != nil {
	t.Fatal(err)
}
restarted, err := NewObjectFoundationStore(client, "ns", "heads")
if err != nil {
	t.Fatal(err)
}
got, actual, err := restarted.Load(t.Context(), "GRU")
if err != nil || actual != etag || got.ResourceIDs["vault"] != record.ResourceIDs["vault"] {
	t.Fatalf("read=%+v etag=%s err=%v", got, actual, err)
}
got.Epoch = 2
if _, err := restarted.CompareAndSwap(t.Context(), got, actual); err != nil {
	t.Fatal(err)
}
if _, err := store.CompareAndSwap(t.Context(), record, etag); err != ErrFoundationConflict {
	t.Fatalf("stale writer: %v", err)
}
if _, err := store.CompareAndSwap(t.Context(), record, ""); err != ErrFoundationConflict {
	t.Fatalf("duplicate founder: %v", err)
}

publish(scope, now.Add(time.Hour))
if _, err := reader.AuthorizedRegions(t.Context()); err != nil {
	t.Fatal(err)
}
if _, err := reader.AuthorizedBootstrapMaterial(t.Context(), "GRU"); err == nil {
	t.Fatal("foundation-only scope authorized root generation")
}
if _, err := reader.InfrastructureSpend(t.Context()); err == nil {
	t.Fatal("foundation-only scope authorized fleet growth")
}
ownedCompartments := grant.Regions[0].Plan["resource_ids"].(map[string]any)
ownedCompartments["network_compartment"] = "ocid1.compartment.oc1..network"
ownedCompartments["workload_compartment"] = "ocid1.compartment.oc1..workload"
spendDigest, err := FoundationInfrastructureScopeDigest(grant)
if err != nil {
	t.Fatal(err)
}
grant.InfrastructureSpend = &InfrastructureSpendIntent{BudgetID: entityid.New(), Currency: "USD", MonthlyLimitMinor: 9000, ScopeSHA256: spendDigest}
publish(scope, now.Add(time.Hour))
spend, err := reader.InfrastructureSpend(t.Context())
if err != nil || !spend.ValidAt(now) || spend.ScopeDigest() != spendDigest || spend.MonthlyLimitMinor() != 9000 || spend.GrantDigest() != reader.home.GrantSHA256 || len(spend.Footprint().Regions[0].CompartmentIDs) != 5 {
	t.Fatalf("spend=%+v err=%v", spend, err)
}

copyScope := spend.Footprint()
copyScope.Regions[0].CompartmentIDs[0] = "foreign"
if spend.Footprint().Regions[0].CompartmentIDs[0] == "foreign" {
	t.Fatal("fleet spend getter leaked mutable scope")
}

for _, wrong := range []InfrastructureSpendIntent{
	{BudgetID: entityid.New(), Currency: "BRL", MonthlyLimitMinor: 9000, ScopeSHA256: spendDigest},
	{BudgetID: entityid.New(), Currency: "USD", MonthlyLimitMinor: 11000, ScopeSHA256: spendDigest},
	{BudgetID: entityid.New(), Currency: "USD", MonthlyLimitMinor: 9000, ScopeSHA256: strings.Repeat("0", 64)},
} {
	grant.InfrastructureSpend = &wrong
	publish(scope, now.Add(time.Hour))
	if _, err := reader.InfrastructureSpend(t.Context()); err == nil {
		t.Fatal("unbound or excessive fleet authority admitted")
	}
}
grant.InfrastructureSpend = nil
publish(scope, now.Add(time.Hour))
if _, err := reader.OCIRIssuer(t.Context(), "gru.ocir.io/ns/terrabase"); err == nil {
	t.Fatal("foundation-only scope authorized OCIR IAM and token issuance")
}
grant.ReleaseAuthorities = []ContainerReleaseAuthorityIntent{{ImageRepository: "gru.ocir.io/ns/terrabase"}}
grant.OCIRIssuances = []OCIRIssuerIntent{{RegistryHost: "gru.ocir.io", OCIRegion: "sa-saopaulo-1", RepositoryCompartmentID: target.CompartmentOCID, RepositoryName: "terrabase", RegistryNamespace: "ns", PrincipalName: "ts-pull", PrincipalEmail: "ocir-pull@terrascale.tech", VaultTarget: vaultsecret.Target{CompartmentID: target.CompartmentOCID, VaultID: target.VaultOCID, KeyID: target.KMSKeyOCID}, SecretName: "ts-pull-credential"}}
publish(scope, now.Add(time.Hour))
issuer, err := reader.OCIRIssuer(t.Context(), "gru.ocir.io/ns/terrabase")
if err != nil || !issuer.IsVerified() || issuer.InstallationID() != reader.home.InstallationID || issuer.GrantDigest() != reader.home.GrantSHA256 || issuer.Intent() != grant.OCIRIssuances[0] {
	t.Fatalf("issuer=%+v err=%v", issuer, err)
}
for _, repository := range []string{"ts-auth", "function-worker"} {
	intent := grant.OCIRIssuances[0]
	intent.RepositoryName = repository
	intent.PrincipalName, intent.PrincipalEmail, intent.SecretName, err = OCIRServiceIdentity(grant.InstallationID, "gru.ocir.io/ns/"+repository)
	if err != nil {
		t.Fatal(err)
	}
	grant.OCIRIssuances = append(grant.OCIRIssuances, intent)
	grant.ReleaseAuthorities = append(grant.ReleaseAuthorities, ContainerReleaseAuthorityIntent{ImageRepository: "gru.ocir.io/ns/" + repository})
}
publish(scope, now.Add(time.Hour))
issuers, err := reader.OCIRIssuers(t.Context())
if err != nil || len(issuers) != 3 {
	t.Fatalf("multi-repository issuers=%+v err=%v", issuers, err)
}
for _, expected := range issuers {
	selected, err := reader.OCIRIssuer(t.Context(), expected.ImageRepository())
	if err != nil || selected != expected {
		t.Fatalf("exact selected issuer=%+v err=%v", selected, err)
	}
}
for _, unapproved := range []string{"", "*", "gru.ocir.io/ns/unapproved", "sa-saopaulo-1.ocir.io/ns/terrabase"} {
	if _, err := reader.OCIRIssuer(t.Context(), unapproved); err == nil {
		t.Fatalf("unapproved repository selector accepted: %q", unapproved)
	}
}
for _, test := range []struct {
	name   string
	mutate func(*FoundationGrant)
}{
	{"missing", func(g *FoundationGrant) { g.OCIRIssuances = g.OCIRIssuances[:2] }},
	{"no issuers", func(g *FoundationGrant) { g.OCIRIssuances = nil }},
	{"unbound", func(g *FoundationGrant) { g.OCIRIssuances[0].RepositoryName = "other" }},
	{"no releases", func(g *FoundationGrant) { g.ReleaseAuthorities = nil }},
	{"duplicate", func(g *FoundationGrant) { g.OCIRIssuances = append(g.OCIRIssuances, g.OCIRIssuances[0]) }},
	{"principal reused", func(g *FoundationGrant) { g.OCIRIssuances[1].PrincipalName = g.OCIRIssuances[0].PrincipalName }},
	{"email reused", func(g *FoundationGrant) {
		g.OCIRIssuances[1].PrincipalEmail = strings.ToUpper(g.OCIRIssuances[0].PrincipalEmail)
	}},
	{"recipient reused", func(g *FoundationGrant) { g.OCIRIssuances[1].SecretName = g.OCIRIssuances[0].SecretName }},
	{"host path", func(g *FoundationGrant) { g.OCIRIssuances[0].RegistryHost += "/ns" }},
	{"host alias", func(g *FoundationGrant) { g.OCIRIssuances[0].RegistryHost = "sa-saopaulo-1.ocir.io" }},
	{"physical alias", func(g *FoundationGrant) {
		g.ReleaseAuthorities = append(g.ReleaseAuthorities, ContainerReleaseAuthorityIntent{ImageRepository: "sa-saopaulo-1.ocir.io/ns/terrabase"})
	}},
	{"wrong region", func(g *FoundationGrant) { g.OCIRIssuances[0].OCIRegion = "us-ashburn-1" }},
	{"foreign vault", func(g *FoundationGrant) {
		g.OCIRIssuances[0].VaultTarget.VaultID = "ocid1.vault.oc1.sa-saopaulo-1.foreign"
	}},
	{"wildcard", func(g *FoundationGrant) { g.OCIRIssuances[0].RepositoryName = "*" }},
	{"issuer bound", func(g *FoundationGrant) { g.OCIRIssuances = make([]OCIRIssuerIntent, 65) }},
	{"release bound", func(g *FoundationGrant) { g.ReleaseAuthorities = make([]ContainerReleaseAuthorityIntent, 65) }},
} {
	t.Run(test.name, func(t *testing.T) {
		validGrant := grant
		grant.OCIRIssuances = slices.Clone(validGrant.OCIRIssuances)
		grant.ReleaseAuthorities = slices.Clone(validGrant.ReleaseAuthorities)
		test.mutate(&grant)
		publish(scope, now.Add(time.Hour))
		_, rejected := reader.OCIRIssuers(t.Context())
		grant = validGrant
		if rejected == nil {
			t.Fatal("invalid issuance scope admitted")
		}
	})
}
grant.OCIRIssuances[0].VaultTarget.VaultID = "ocid1.vault.oc1.sa-saopaulo-1.foreign"
publish(scope, now.Add(time.Hour))
if _, err := reader.OCIRIssuer(t.Context(), "gru.ocir.io/ns/terrabase"); err == nil {
	t.Fatal("foreign Vault was authorized for OCIR IAM and token issuance")
}
grant.OCIRIssuances = nil
grant.ReleaseAuthorities = nil
grant.Regions[0].BootstrapMaterial = material
publish(scope, now.Add(time.Hour))
verified, err := reader.AuthorizedBootstrapMaterial(t.Context(), "GRU")
if err != nil || !verified.IsVerified() || verified.PlanDigest() != material.PlanSHA256 || verified.EscrowTarget() != target || !verified.ExpiresAt().Equal(now.Add(time.Hour)) {
	t.Fatalf("verified=%+v err=%v", verified, err)
}

if _, err := verified.Startup(); err == nil {
